#include "benchmark.h"
#include <cuda_runtime.h>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <thread>
#include <vector>
namespace gcb {
#define CK(x) do { cudaError_t e=(x); if(e!=cudaSuccess) throw std::runtime_error(std::string(#x)+": "+cudaGetErrorString(e)); } while(0)
using Clock=std::chrono::steady_clock;
__global__ void burn(unsigned long long cycles,unsigned long long seed){unsigned long long t=clock64(),x=threadIdx.x+blockIdx.x*1315423911ULL+seed;while(clock64()-t<cycles)x=x*2862933555777941757ULL+3037000493ULL;if(x==7)asm volatile("");}
__global__ void fmaProbe(float* o,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;float x=1.0001f+(i&31)*1e-5f;for(int j=0;j<n;j++)x=fmaf(x,1.00001f,0.99999f);o[i]=x;}
__global__ void triad(const float*a,const float*b,float*c,size_t n){size_t i=(size_t)blockIdx.x*blockDim.x+threadIdx.x;if(i<n)c[i]=a[i]*1.25f+b[i];}
static double elapsed(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::milli>(b-a).count();}
static double pct(std::vector<double> v,double p){std::sort(v.begin(),v.end());return v.empty()?0:v[(size_t)std::ceil(p*(v.size()-1))];}
static unsigned long long cycles(double m,int dev){int khz=0;CK(cudaDeviceGetAttribute(&khz,cudaDevAttrClockRate,dev));return (unsigned long long)(std::max(1.0,m)*khz*1000.0);}
struct GC{cudaExecutionContext_t c{};cudaStream_t s{};unsigned sms=0;GC()=default;GC(const GC&)=delete;GC&operator=(const GC&)=delete;GC(GC&&x)noexcept:c(x.c),s(x.s),sms(x.sms){x.c=nullptr;x.s=nullptr;}~GC(){if(s)cudaStreamDestroy(s);if(c)cudaExecutionCtxDestroy(c);}};
static GC makeGC(cudaDevResource* r,unsigned n,int dev){cudaDevResourceDesc_t d{};CK(cudaDevResourceGenerateDesc(&d,r,n));GC g;CK(cudaGreenCtxCreate(&g.c,d,dev,0));cudaDevResource actual{};CK(cudaExecutionCtxGetDevResource(g.c,&actual,cudaDevResourceTypeSm));g.sms=actual.sm.smCount;CK(cudaExecutionCtxStreamCreate(&g.s,g.c,cudaStreamNonBlocking,0));return g;}
static std::vector<cudaDevResource> pairSplit(int dev,unsigned first,unsigned total){cudaDevResource all{};CK(cudaDeviceGetDevResource(dev,&all,cudaDevResourceTypeSm));if(!first||first>=total)throw std::runtime_error("invalid requested partition");cudaDevSmResourceGroupParams p[2]{};p[0].smCount=first;p[1].smCount=total-first;cudaDevResource out[2]{};CK(cudaDevSmResourceSplit(out,2,&all,nullptr,0,p));return {out[0],out[1]};}
static void writeHeader(const std::string&p){std::ofstream f(p);if(!f)throw std::runtime_error("cannot open CSV");f<<"test,mode,latency_p50_ms,latency_p95_ms,latency_p99_ms,kernel_gpu_time_ms,total_throughput,throughput_unit,background_time_ms,sm_allocation\n";}
static void emit(const std::string&p,const std::string&t,const std::string&m,double p50=0,double p95=0,double p99=0,double gpu=0,double tp=0,const std::string&unit="kernels/s",double bg=0,int sm=-1){std::ofstream f(p,std::ios::app);f<<t<<','<<m<<','<<p50<<','<<p95<<','<<p99<<','<<gpu<<','<<tp<<','<<unit<<','<<bg<<',';if(sm<0)f<<"Full GPU / Unpartitioned";else f<<sm;f<<'\n';std::cout<<t<<" "<<m<<" p50="<<p50<<"ms gpu="<<gpu<<"ms bg="<<bg<<"ms SM="<<(sm<0?-1:sm)<<'\n';}
static void emitProbe(const std::string&p,const std::string&m,double gpu,double tp,const std::string&unit){std::ofstream f(p,std::ios::app);f<<"runComputeAndMemoryThroughput,"<<m<<",NA,NA,NA,"<<gpu<<","<<tp<<","<<unit<<",NA,Full GPU / Unpartitioned\n";std::cout<<"runComputeAndMemoryThroughput "<<m<<" gpu="<<gpu<<"ms throughput="<<tp<<" "<<unit<<"\n";}
static void launch(cudaStream_t s,double m,int blocks,int dev,int seed){burn<<<std::max(1,blocks),256,0,s>>>(cycles(m,dev),seed);CK(cudaGetLastError());}
static void measure(const Options&o,const std::string&test,const std::string&mode,cudaStream_t c,cudaStream_t b,int cb,int bb,int sm){std::vector<double> lat;double gs=0,bs=0;cudaEvent_t a,z,x,y;CK(cudaEventCreate(&a));CK(cudaEventCreate(&z));CK(cudaEventCreate(&x));CK(cudaEventCreate(&y));for(int i=0;i<o.iterations;i++){auto bt=Clock::now();launch(b,4,bb,o.device,i);CK(cudaEventRecord(y,b));std::this_thread::sleep_for(std::chrono::milliseconds(1));auto st=Clock::now();CK(cudaEventRecord(a,c));launch(c,.8,cb,o.device,i+99);CK(cudaEventRecord(z,c));CK(cudaEventSynchronize(z));lat.push_back(elapsed(st,Clock::now()));float g=0;CK(cudaEventElapsedTime(&g,a,z));gs+=g;CK(cudaEventSynchronize(y));bs+=elapsed(bt,Clock::now());}cudaEventDestroy(a);cudaEventDestroy(z);cudaEventDestroy(x);cudaEventDestroy(y);double p50=pct(lat,.5);emit(o.csv,test,mode,p50,pct(lat,.95),pct(lat,.99),gs/o.iterations,p50?1000/p50:0,"kernels/s",bs/o.iterations,sm);}
static void runPrimaryVsGreenContextComparison(const Options&o){cudaStream_t a,b;CK(cudaStreamCreateWithFlags(&a,cudaStreamNonBlocking));CK(cudaStreamCreateWithFlags(&b,cudaStreamNonBlocking));measure(o,"runPrimaryVsGreenContextComparison","primary_two_streams",a,b,4096,8192,-1);cudaStreamDestroy(a);cudaStreamDestroy(b);cudaDevResource all{};CK(cudaDeviceGetDevResource(o.device,&all,cudaDevResourceTypeSm));unsigned al=std::max(1u,all.sm.smCoscheduledAlignment),half=(all.sm.smCount/2/al)*al;auto r=pairSplit(o.device,half,all.sm.smCount);GC c=makeGC(&r[0],1,o.device),bg=makeGC(&r[1],1,o.device);measure(o,"runPrimaryVsGreenContextComparison","two_green_contexts",c.s,bg.s,c.sms*4,bg.sms*8,c.sms);}
static void runSmPartitionSweep(const Options&o){cudaDevResource all{};CK(cudaDeviceGetDevResource(o.device,&all,cudaDevResourceTypeSm));unsigned n=all.sm.smCount,al=std::max(1u,all.sm.smCoscheduledAlignment);for(unsigned q=20;q<=80;q+=10){unsigned x=std::max(al,(unsigned)std::round(n*q/100.0/al)*al);if(x>=n)x=n-al;try{auto r=pairSplit(o.device,x,n);GC c=makeGC(&r[0],1,o.device),b=makeGC(&r[1],1,o.device);measure(o,"runSmPartitionSweep",std::to_string(q)+"pct_critical",c.s,b.s,c.sms*4,b.sms*8,c.sms);}catch(const std::exception&e){std::cerr<<"SKIP split "<<q<<"%: "<<e.what()<<'\n';}}}
static void runComputeAndMemoryThroughput(const Options&o){int n=1<<24;float*a,*b,*c,*d;CK(cudaMalloc(&a,(size_t)n*4));CK(cudaMalloc(&b,(size_t)n*4));CK(cudaMalloc(&c,(size_t)n*4));CK(cudaMalloc(&d,(size_t)n*4));CK(cudaMemset(a,1,(size_t)n*4));CK(cudaMemset(b,2,(size_t)n*4));cudaEvent_t s,e;CK(cudaEventCreate(&s));CK(cudaEventCreate(&e));int blocks=(n+255)/256;fmaProbe<<<blocks,256>>>(d,4096);CK(cudaGetLastError());CK(cudaEventRecord(s));fmaProbe<<<blocks,256>>>(d,8192);CK(cudaGetLastError());CK(cudaEventRecord(e));CK(cudaEventSynchronize(e));float ms=0;CK(cudaEventElapsedTime(&ms,s,e));emitProbe(o.csv,"fma_compute_probe",ms,(double)n*8192*2/(ms*1e6),"GFLOP/s");triad<<<blocks,256>>>(a,b,c,n);CK(cudaGetLastError());CK(cudaEventRecord(s));triad<<<blocks,256>>>(a,b,c,n);CK(cudaGetLastError());CK(cudaEventRecord(e));CK(cudaEventSynchronize(e));CK(cudaEventElapsedTime(&ms,s,e));emitProbe(o.csv,"memory_triad_probe",ms,(double)n*12/(ms*1e6),"GB/s_nominal");cudaEventDestroy(s);cudaEventDestroy(e);cudaFree(a);cudaFree(b);cudaFree(c);cudaFree(d);}
static void runMultiGreenContextConcurrency(const Options&o){cudaDevResource all{};CK(cudaDeviceGetDevResource(o.device,&all,cudaDevResourceTypeSm));unsigned al=std::max(1u,all.sm.smCoscheduledAlignment);for(unsigned n:{2u,4u,8u}){unsigned groups=n,min=std::max(al,(all.sm.smCount/n/al)*al);cudaDevResource parts[8]{};cudaError_t e=cudaDevSmResourceSplitByCount(parts,&groups,&all,nullptr,0,min);if(e!=cudaSuccess||groups<n){std::cerr<<"SKIP runMultiGreenContextConcurrency "<<n<<" contexts: insufficient aligned SM partitions\n";continue;}std::vector<GC> cs;for(unsigned i=0;i<n;i++)cs.push_back(makeGC(&parts[i],1,o.device));std::vector<cudaEvent_t> done(n);for(auto&v:done)CK(cudaEventCreate(&v));auto bt=Clock::now();for(unsigned i=1;i<n;i++){launch(cs[i].s,8,cs[i].sms*8,o.device,i);CK(cudaEventRecord(done[i],cs[i].s));}cudaEvent_t a,z;CK(cudaEventCreate(&a));CK(cudaEventCreate(&z));auto st=Clock::now();CK(cudaEventRecord(a,cs[0].s));launch(cs[0].s,.8,cs[0].sms*4,o.device,777);CK(cudaEventRecord(z,cs[0].s));CK(cudaEventSynchronize(z));double lat=elapsed(st,Clock::now());float gm=0;CK(cudaEventElapsedTime(&gm,a,z));for(unsigned i=1;i<n;i++)CK(cudaEventSynchronize(done[i]));emit(o.csv,"runMultiGreenContextConcurrency",std::to_string(n)+"_green_contexts",lat,lat,lat,gm,1000/lat,"kernels/s",elapsed(bt,Clock::now()),cs[0].sms);for(auto v:done)cudaEventDestroy(v);cudaEventDestroy(a);cudaEventDestroy(z);}}
static void runWorkqueueScopeComparison(const Options&o){for(auto scope:{cudaDevWorkqueueConfigScopeDeviceCtx,cudaDevWorkqueueConfigScopeGreenCtxBalanced}){cudaDevResource sm{},wq{};CK(cudaDeviceGetDevResource(o.device,&sm,cudaDevResourceTypeSm));wq.type=cudaDevResourceTypeWorkqueueConfig;wq.wqConfig.device=o.device;wq.wqConfig.sharingScope=scope;wq.wqConfig.wqConcurrencyLimit=2;cudaDevResource pack[2]={sm,wq};GC a=makeGC(pack,2,o.device),b=makeGC(pack,2,o.device);measure(o,"runWorkqueueScopeComparison",scope==cudaDevWorkqueueConfigScopeDeviceCtx?"device_ctx_scope":"green_ctx_balanced",a.s,b.s,a.sms*4,b.sms*4,a.sms);}}
void run(const Options&o){int n=0;CK(cudaGetDeviceCount(&n));if(o.device<0||o.device>=n)throw std::runtime_error("invalid device ordinal");CK(cudaSetDevice(o.device));cudaDeviceProp p{};CK(cudaGetDeviceProperties(&p,o.device));std::cout<<"GPU "<<p.name<<" CUDA runtime "<<CUDART_VERSION<<'\n';writeHeader(o.csv);if(o.test==0||o.test==1)runPrimaryVsGreenContextComparison(o);if(o.test==0||o.test==2)runSmPartitionSweep(o);if(o.test==0||o.test==3)runComputeAndMemoryThroughput(o);if(o.test==0||o.test==4)runMultiGreenContextConcurrency(o);if(o.test==0||o.test==5)runWorkqueueScopeComparison(o);}
}
int main(int argc,char**argv){try{gcb::Options o;for(int i=1;i<argc;i++){std::string a=argv[i];if(a=="--device"&&i+1<argc)o.device=std::stoi(argv[++i]);else if(a=="--iterations"&&i+1<argc)o.iterations=std::max(1,std::stoi(argv[++i]));else if(a=="--suite"&&i+1<argc){std::string t=argv[++i];if(t=="all")o.test=0;else if(t=="primary-vs-green")o.test=1;else if(t=="sm-partition-sweep")o.test=2;else if(t=="compute-memory-throughput")o.test=3;else if(t=="multi-green-context")o.test=4;else if(t=="workqueue-scope")o.test=5;else throw std::runtime_error("unknown suite: "+t);}else if(a=="--csv"&&i+1<argc)o.csv=argv[++i];else if(a=="--help"){std::cout<<"--suite all|primary-vs-green|sm-partition-sweep|compute-memory-throughput|multi-green-context|workqueue-scope --device N --iterations N --csv FILE\n";return 0;}else throw std::runtime_error("unknown argument "+a);}gcb::run(o);return 0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 1;}}
